/**
 * Phones and small tablets: touch-first and memory-constrained. Decided once at load (a device does
 * not change class mid-session) and used for render budgets: pixel ratio, sky samples, texture size.
 */
const PHONE_SHORT_SIDE_PX = 900

export const isConstrainedDevice: boolean =
  typeof window !== 'undefined' &&
  window.matchMedia('(pointer: coarse)').matches &&
  Math.min(window.screen.width, window.screen.height) < PHONE_SHORT_SIDE_PX

/** 8K maps on desktop; 4K copies (generated by scripts/make-mobile-textures.ps1) on phones. */
export const hiResPath = (path: string): string => (isConstrainedDevice ? path.replace('/textures/hires/', '/textures/hires/4k/') : path)
